INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Siralim', 'Siralim is a deep RPG with light roguelike elements that allows you to summon and customize hundreds of creatures to fight in strategic battle. Fight your way through randomly generated dungeons and complete randomized quests. Find rare treasure and use it to upgrade your castle, empower your creatures, craft powerful artifacts, learn new spells, and much more.' FROM games WHERE igdb_id = 35454 ON CONFLICT (game_id, language_code) DO NOTHING;
