INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Questerium: Sinister Trinity HD - Collector''s Edition', 'Financed by the banker, the professor builds an evil machine that causes the meteor''s energy to spin out of control, destroying the city and mutating its plants and animals. Citizens are evacuated, but rescuers fail to find and evacuate two children. In Questerium: Sinister Trinity HD, you play the investigator hired to work the case, and it''s up to you to destroy the evil machine, rescue the abandoned children, save the city and arrest the professor!' FROM games WHERE igdb_id = 36234 ON CONFLICT (game_id, language_code) DO NOTHING;
