INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go to Bed: Survive the Night', 'A slithering, creeping evil lurks just beyond safety of the light. Indeed, the King of Shadows is up to no good this night, and his beastly minions are getting hungrier by the second. You had better get clicking if you want to live! Can you survive until dawn in this whimsical and spooky nightmare outing?' FROM games WHERE igdb_id = 34144 ON CONFLICT (game_id, language_code) DO NOTHING;
