INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzledrome', 'Make every row and column a palindrome in as few moves as possible! Challenge your mind with a game that takes thought, agility, and creative thinking to solve unique palindrome puzzles. Swap the tiles until all of the rows and columns are palindromes, in as few moves as possible. Inspired by symmetry, Sudoku and matching games, Puzzledrome takes tiled based puzzling to the next level! What''s left is right, what''s up is down…' FROM games WHERE igdb_id = 200061 ON CONFLICT (game_id, language_code) DO NOTHING;
