INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Walk Simulator', 'Race against dinosaurs or friends in this local 1 - 4 player multi-player physics game. Dino Walk Sim features 34 dinosaurs and creatures from the Triassic, Jurassic, and Cretaceous periods! Race against other dinosaurs or grab some friends and huddle around your phone or tablet for lots of silly dinosaur fun. Featuring 10 racing locations! Featuring advanced physics simulations for extremely in-accurate and silly dinosaur walking movement. Enjoy an authentic early real-time 3D graphics look reminiscent of 1st generation ''90s era 3D game consoles and arcades. "Dinosaurs are from the Mesozoic era, and so are the graphics!" These graphics are prehistoric!' FROM games WHERE igdb_id = 175866 ON CONFLICT (game_id, language_code) DO NOTHING;
