INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nocturne: Rebirth', 'Nocturne: Rebirth is a popular 10 to 20-hour (story-wise) JRPG originally created using RPG Maker XP in 2009 by Shou (or Cogwheel). It is actually the remake of the game Nocturne created using RPG Maker 2000 way back in 2002. The differences between the two include new graphics and a new battle system, with only the story virtually unchanged. It was fan translated by eplipswich.' FROM games WHERE igdb_id = 122548 ON CONFLICT (game_id, language_code) DO NOTHING;
