INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Train Driver Journey 4 - Introduction to Steam', 'Your journey as a Train Driver begins today in this realistic train simulator! From the makers of the world-leading Trainz series, take charge of a wide range of powerful locos, hauling thousands of tonnes of freight, shunting in the yard or shuttling passengers along suburban lines. Explore amazingly detailed and interactive routes from around the world from a variety of camera angles. Fun for ages 5 to 95!
