INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reverse Side', 'An extraterrestrial spacecraft was discovered during the last manned mission to the moon in 1972. Although all information regarding this was classified, the USSR discovered it and in 1976 organized an expedition to explore the wreckage. 2 years later regular flights to the moon had become common and the scientific research center Orbit was built but this information remained classified.' FROM games WHERE igdb_id = 17733 ON CONFLICT (game_id, language_code) DO NOTHING;
