INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tick: The Time Based Puzzle Game', 'Test your timing and your patience in this unique casual puzzle game. Set over the backdrop of retro minimalist art style you can choose from 3 different game modes. Play your way through 50 stages of increasing difficult puzzles in Stage Mode. See how fast you really are in Speed Mode. Try out your own level created via the in-game Level Editor.' FROM games WHERE igdb_id = 34794 ON CONFLICT (game_id, language_code) DO NOTHING;
