INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('corn-buster', 42565, '2015-08-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9v39.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8afo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corn Buster', 'Corn Buster is a Super Nintendo game developed by Engine Software. The game is the story of a dragon named Globey, who sets out to defeat the person who’s stolen all the cornflakes in the world. The gameplay is an interesting mix of an Arkanoid-Style ball-and-paddle game and a vertical scrolling shooter. The game quietly began development around 1994, and was canceled soon after interest in the Super Nintendo waned in light of the release of Sony’s Playstation. Some time ago, Engine Software released a ROM of the game for free download on their website. The download page has since been removed, but the ROM is still easily obtainable. The game was 70-80% completed before it was canceled.
