INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Object: Detective Story about Ancient Case Premium', 'Are you ready to accept a new challenge and set off to an incredible journey? Then welcome to the "Detective Story: An Ancient Case", a new mysterious and unique Hidden Object game! Here you will met a girl who will face a difficult task to get to the truth. One day she wakes up in the middle of the night from nightmares and sees a bloodied note beside the bed. Having recognised the address of her best friend, she decides to reveal the secret. Join her in this difficult task.' FROM games WHERE igdb_id = 175496 ON CONFLICT (game_id, language_code) DO NOTHING;
