INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nexus-the-zoraidian-oracle', 202883, '2015-05-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4sm7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch65l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nexus: The Zoraidian Oracle', 'Based in the world of Tyanaphos, Nexus: The Zoraidian Oracle is a strategic solitaire card game inspired by Hanafuda (a traditional Japanese flower card game similar to mahjong or rummy), steeped in original Western fantasy and Tarot-like themes. Featuring a 144-card deck comprised of minor and major arcana and additional categories unique to Tyanaphos, as well as a customizable user interface, Nexus is next-level solitaire. Gameplay can be relaxing or challenging to your critical thinking skills depending on your approach. The rules expand on familiar solitaire mechanics, rewarding more creative set-building strategies with point rewards and achievements.' FROM games WHERE igdb_id = 202883 ON CONFLICT (game_id, language_code) DO NOTHING;
