INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Press Your Luck', 'The game of Red Light Green Light goes mobile! Tap as many times as you can while the light is green. However, tapping when red means that you''ve been caught. Beat your high score and challenge the world to be as sneaky as you!' FROM games WHERE igdb_id = 172073 ON CONFLICT (game_id, language_code) DO NOTHING;
