INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-ingenious-machine-new-and-improved-edition', 50220, '2015-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kmqomsxw6a4lxhmbraye.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mrz2uvcdohvzx4mlqyxb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ingenious Machine: New and Improved Edition', 'The Ingenious Machine is a single-player physics-based puzzle game. The player is presented with a series of light bulbs that they must switch on, by creating elaborate machines out of a pre-defined array of gadgets. The gadgets include gears, conveyor belts, magnets, weights, explosives, and lasers. Points are awarded for creativity, but deducted for each failed attempt at building a working machine. This is an extended edition of the original Ingenious Machine, which was previously released for Android and iOS. The "New and Improved Edition" features the following updates: - Twice as many levels. Fifty in total. - Improved music. - Improved graphics. - New gadget types; including springs, flame-throwers, balloons, and a cloning machine! It''s all about user-generated content and creative problem-solving. And also dynamite.' FROM games WHERE igdb_id = 50220 ON CONFLICT (game_id, language_code) DO NOTHING;
