INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Harvest', 'Meet Zombie Harvest: a sarcastic parody of popular games, with a twist! Shoot, defend, attack, and win! Throw anything you have at hand at the ghouls, and have fun! It''s easy to shoot, impossible to stop! Protect your veggie garden until last zombies get shot.' FROM games WHERE igdb_id = 87158 ON CONFLICT (game_id, language_code) DO NOTHING;
