INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bearzerkers', 'Bearzerkers is a local multiplayer game of two halves, with a focus on indirect combat and avoidance. HUNT pits you and your friends against each other; where you don''t need to run faster than the bear to survive, just faster than the person next to you. Gauntlet is the ultimate game of moment to moment cooperation where every second counts and a single slip up can be the end for you and your team.' FROM games WHERE igdb_id = 17881 ON CONFLICT (game_id, language_code) DO NOTHING;
