INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breath of Light: Relaxing Puzzler', 'Breath of Light is a meditative and beautiful puzzle game with a hypnotic soundtrack by Winterpark. Hold a quiet moment. Inspired by modern minimalism combined with a range of meditative art styles, from Zen Gardening to Sumi inks and Indian Buddhist art. Easy to use, flowing and set to a gorgeous and serene soundscape. Best played with headphones. Players guide energy by moving rocks around the mystic garden, setting them in place and watching the energy settle into its new flow.' FROM games WHERE igdb_id = 175551 ON CONFLICT (game_id, language_code) DO NOTHING;
