INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarMap 3D Plus', 'No in-app purchases necessary! StarMap 3D Plus is the portable star atlas for beginners or advanced astronomers. Use StarMap 3D Plus to find the planets, stars, constellations, star clusters, galaxies, and nebulae visible to you based on your location and time. StarMap 3D will even use the compass to automatically align the map!' FROM games WHERE igdb_id = 41524 ON CONFLICT (game_id, language_code) DO NOTHING;
