INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Odoru? Pokémon Ongakutai', 'Odoru? Pokémon Ongakutai is a rhythm game made to promote the short film Pikachu and the Pokémon Band. The player must tap buttons on the screen in time with falling musical notes, as a Pokémon of their choice dances in the foreground. Racking up a combo will reward the player with bonus time, during which a score multiplier and backup Pokémon dancers appear. Additional Pokémon species may be unlocked as the game is played.' FROM games WHERE igdb_id = 60055 ON CONFLICT (game_id, language_code) DO NOTHING;
