INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tower of Guns: Steelbook Limited Edition', 'Ascend the Tower of Guns and return to the days of circle-strafing, rocket-jumping, and twitch-based action. Tower of Guns is a throwback first-person shooter with a healthy sprinkling of roguelike-ish-y elements. Every turn brings a surprise and around every corner lies certain death! Or a new weird item! Or a ... Hugbot? Filled with random levels, crazy bosses, bizzare powerups, and tons of unlockable weapons and items, each time you step into the Tower of Guns you''ll have a fresh gaming experience.' FROM games WHERE igdb_id = 42949 ON CONFLICT (game_id, language_code) DO NOTHING;
