INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cap''n Marcela parrot charmer', 'The mighty Puffy Shirt Morgan and his band of pirates lay siege to the small Crabs Bay village and threaten to burn it entirely if people don''t surrender before sunrise. Fortunately, the intrepid Marcela is determined not to give up so easily and to thwart the plans of the vile pirate. The clock is ticking and you''ll have to help her to get rid of the attackers in this very nice adventure game.' FROM games WHERE igdb_id = 28344 ON CONFLICT (game_id, language_code) DO NOTHING;
