INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Realm 2: Princess of Ice', 'Mad Head presents the exciting continuation of the Dark Realm story line! This time, a magic bear summons you to help save the neighboring kingdom of Nypha. Find out what has Nypha and its princess trapped in a death grip of cold. As a fire-wielder, you have a few tricks up your sleeve, but the bear''s given you some special abilities too! You''ll be thrilled by the fun new Match-3 mechanic and enjoy adventurous interactions along the way.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46957 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
