INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Frontera', 'Wild Frontera is a top-down action shooter set in a western-fantasy world. You are a lonesome gunslinger, that will have to get rid of hordes of enemies and defeat spectacular bosses in order to escape to the frontier.Armed with a rusty six-shooter that you can swap very quickly for new weapons, for a fistfull of dollars looted while playing the game.' FROM games WHERE igdb_id = 17972 ON CONFLICT (game_id, language_code) DO NOTHING;
