INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Ages: Medieval - Limited Special Edition', 'It is the year 1050 AD. At the beginning of the High Middle Ages development in Europe has seen an unprecedented level of progress and a rapidly growing population spreads across the length and breadth of the continent. New frontiers are explored, settlements founded and vast trading routes established. As the head of one of these small settlements, it falls upon you to lead your people towards greatness.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 42950 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
