INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lemurzin', 'Lemurzin is a unique crazy runner game. Play for mad Lemurzin and collect hamburgers, cola, ice cream and french fries. Dodge the dangerous obstacles and bullets. And remember police turtle always will pursue you, turtle which is flying on a rocket with a deadly weapon. This is crazy game from the creators of the cartoon Kut Stupid.' FROM games WHERE igdb_id = 34116 ON CONFLICT (game_id, language_code) DO NOTHING;
