INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Dimensions: Homecoming', 'Years ago, your parents disappeared while investigating an abandoned mansion in Whispering Hollows. Since then, you’ve been traveling the country, tracking down Dark Dimensions and seeking answers to your parents’ strange disappearance. Finally, after all these years, the truth behind your family’s greatest tragedy will be revealed. It’s time to visit Barton Mansion, where it all began. Just watch your back, because this mansion is far from abandoned. All of your training and experience has led to this haunting Hidden Object Puzzle Adventure game!' FROM games WHERE igdb_id = 139787 ON CONFLICT (game_id, language_code) DO NOTHING;
