INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Civil War: Stonewall', 'This is the first in a series of games from HexWar to be based on the ''Great Battles of the American Civil War'' board games, which started with the classic game ''Terrible Swift Sword''. This series recreates the significant battles of the American Civil War. Each game in this series is a grand tactical, regimental-level simulation of a single battle, enabling players to test their generalship under the same challenges faced by the Union and Confederate commanders.' FROM games WHERE igdb_id = 175148 ON CONFLICT (game_id, language_code) DO NOTHING;
