INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grave Prosperity: Redux- part 1', 'Grave Prosperity: Redux follows Amber Ridge as she finds herself broken down on a mountain road. Without any reception and no signs of passers-by, she is forced to walk to the nearest town- Prosperity. A place that knows no God and exists only to make you suffer. Utilize a deadly arsenal of agility, blade-work and gun-play to fend off the darkness that stalks your every movement. Collect EXP through solving puzzles and slaying grotesque creatures in order to upgrade your stats to better suit you survival needs.' FROM games WHERE igdb_id = 35553 ON CONFLICT (game_id, language_code) DO NOTHING;
