INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Euro Train Simulator', 'Euro Train Simulator is the first in a planned series of high-quality, feature-rich railroad simulation games covering every major destination in the world. Featuring an intuitive, easy to use interface, the game lets users play Career Mode to accomplish each scenario and unlock new trains and routes. Career accomplishments are featured on a leader board. On the other hand, Quick Mode lets you choose the train, route, source and destination stations, weather and the time of the day for the simulation.' FROM games WHERE igdb_id = 202231 ON CONFLICT (game_id, language_code) DO NOTHING;
