INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 11548 AND c.slug = 'matrix-software' ON CONFLICT DO NOTHING;
