INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Booming Boy', 'Booming Boy features all the components required that will make you enjoy as a classic Japanese arcade game in the first half of the 80''s.Place as many bombs as you can, destroy all the obstacles in order to find the hidden power-ups and eliminate your enemies quickly before time runs out. 5 areas consisting of 5 stages with a lot of enemies plus bosses. You will have hours of fun reliving those wonderful moments of amusement arcades.' FROM games WHERE igdb_id = 41732 ON CONFLICT (game_id, language_code) DO NOTHING;
