INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures of Poco Eco: Lost Sounds', 'Discover a new world where there’s a lot to see and even more to hear. Help Poco Eco, the curious explorer complete his mission. Your goal is to help Poco Eco and his tribe find their Lost Sounds that they’ve lost by solving the mini puzzles and completing all twelve 3D animated levels. By downloading Adventures of Poco Eco you also get free access to Iamyank’s new LP.' FROM games WHERE igdb_id = 58991 ON CONFLICT (game_id, language_code) DO NOTHING;
