INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uneven Dream', 'Uneven Dream is a collaborative Yume Nikki fangame founded by Factory and Nex. The game is similar to Yume 2kki (and, by extension, Yume Nikki: Solitude and Yume Shikki) by being made primarily of contributions submitted by a multitude of developers. In 2016, Uneven Dream underwent an extended hiatus until being revived in 2019.' FROM games WHERE igdb_id = 141411 ON CONFLICT (game_id, language_code) DO NOTHING;
