INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mabinogi Duel', 'Mabinogi Duel is a tactical trading card game (TCG) for smartphones. Players build decks using 12 cards, selecting from a diverse card collection to create strategic combinations. The game features a Story Mode that introduces players to game mechanics, and includes a PVP Arena for real-time player duels. Additional gameplay elements include card trading and deck-building strategies.' FROM games WHERE igdb_id = 23653 ON CONFLICT (game_id, language_code) DO NOTHING;
