INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crunchy Numbers Math Arcade', 'Crunchy Numbers Math Arcade is a fun, challenging, & educational math game. Use that amazing brain of yours to help Cruncher Bot eat the correct numbers. Cruncher Bot is always hungry for the right multiple, prime, factor, & roman numeral, but the Red Chompers are trying to stop him from feeding his mathematical appetite. Build up a combo by eating consecutive correct numbers to greatly increase your high score or just play casually for fun.' FROM games WHERE igdb_id = 205082 ON CONFLICT (game_id, language_code) DO NOTHING;
