INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AntharioN', 'Antharion is an epic old-school fantasy RPG that combines tactical turn-based combat with the freedom of a huge living-breathing open world. You''ll create and customize a party of four: choosing from seven races, nine classes and fifteen skills, before setting out to explore the fully interactive continent of Antharion. Explore dungeons, get thrown in jail, discover hidden passageways, burglarize homes, read books, create potions, become and infamous pickpocket, embark on a journey at sea and discover uncharted islands or persuade NPCs to do your bidding. In Antharion no play style is off limits.' FROM games WHERE igdb_id = 17227 ON CONFLICT (game_id, language_code) DO NOTHING;
