INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color Lines - Classic Puzzle', 'Welcome to the world of Line 98, where classic gameplay meets modern challenges! Dive into a mesmerizing puzzle experience that will test your strategic skills and captivate your mind. In Line 98, your objective is simple yet addictively challenging: arrange colorful balls into lines of the same color to clear the board and earn points. With intuitive controls and endless levels, Line 98 offers hours of entertainment for players of all ages.' FROM games WHERE igdb_id = 103142 ON CONFLICT (game_id, language_code) DO NOTHING;
