INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boogeyman', 'Young Thomas has just moved into his new house; his parents snapping up the deal for the property without realising its dark past. Thomas finds a cassette player with a tape left inside along with a much needed flashlight. As darkness falls, he soon realises he is not alone within the room.' FROM games WHERE igdb_id = 19015 ON CONFLICT (game_id, language_code) DO NOTHING;
