INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pizzarian', 'The year is 2010 A.D.—The Future—and your mission is to be the coolest pizza delivery business in the Jovian system. Cut through traffic, avoid the police, and deliver pizzas to the moons of Jupiter! Save up your money to buy better ships and upgrade your pizzeria. Just look out for the competition...!' FROM games WHERE igdb_id = 36010 ON CONFLICT (game_id, language_code) DO NOTHING;
