INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Soup', 'It''s the last day of school, and Moe has to confess to one of the three boys in her school. The cheerful Guro, the stoic Keith or the meek Charlie. She''s then invited to pass the day at her crush''s home. Curious to know more about him, Moe begins to investigate the house and finds that not everything is as it seems...' FROM games WHERE igdb_id = 150182 ON CONFLICT (game_id, language_code) DO NOTHING;
