INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Date A Live Twin Edition: Rio Reincarnation', 'Date A Live Twin Edition: Rio Reincarnation is a Japanese visual novel and the third game based on the Date A Live light novel franchise. It features the stories from the first two games, Rinne Utopia and Ars Install, as well as a sequel story set after the first two games, Rio Reincarnation. Rio Reincarnation can be started after either clearing the first two stories or clearing the digest version of the first two stories.' FROM games WHERE igdb_id = 11830 ON CONFLICT (game_id, language_code) DO NOTHING;
