INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhythm Heaven Megamix', 'Test your rhythm by chopping wood, sticking speeding viruses with forks and playing badminton while flying an airplane, all in time to catchy tunes in this deceptively challenging rhythm game. The accessible controls and catchy music, combined with the new visual feedback system, make this a great entry in the Rhythm Paradise series. Can you match the beat and reach Rhythm Paradise ?' FROM games WHERE igdb_id = 18220 ON CONFLICT (game_id, language_code) DO NOTHING;
